using GastricCancerDetection.Application.Interfaces; using GastricCancerDetection.Infrastructure.Persistence; using Microsoft.EntityFrameworkCore;
namespace GastricCancerDetection.Infrastructure.Services;
public class GenomeAnalysisService : IGenomeAnalysisService { private readonly GastricCancerDbContext _db; private readonly IVariantAnalysisService _variant; private readonly ICNVAnalysisService _cnv; private readonly ICfDNADetectabilityService _cf; private readonly ICandidateScoringService _rank; public GenomeAnalysisService(GastricCancerDbContext db,IVariantAnalysisService variant,ICNVAnalysisService cnv,ICfDNADetectabilityService cf,ICandidateScoringService rank){_db=db;_variant=variant;_cnv=cnv;_cf=cf;_rank=rank;} public async Task<object> RunAdvancedPipelineAsync(int runId,CancellationToken ct=default){var run=await _db.AnalysisRuns.FindAsync(new object[]{runId},ct)??throw new InvalidOperationException("Analysis run not found."); run.StartTime=DateTime.UtcNow; run.StatusId=2; await _db.SaveChangesAsync(ct); try {var nonCoding=await _variant.AnalyzeNonCodingAsync(runId,ct); var cna=await _cnv.AnalyzeAsync(runId,ct); await _cf.CalculateAsync(runId,ct); await _rank.RankAsync(runId,ct); run.StatusId=3; run.EndTime=DateTime.UtcNow; await _db.SaveChangesAsync(ct); return new {runId,nonCodingVariants=nonCoding,cnaRegions=cna,status="Completed"};} catch(Exception ex){run.StatusId=4;run.ErrorMessage=ex.Message;run.EndTime=DateTime.UtcNow;await _db.SaveChangesAsync(ct);throw;} } }
